import pandas as pd
df = pd.read_csv('model_errors_8_9.csv')
def mean_absolute_error(true_answers, predictions):
    if len(true_answers) != len(predictions) or not true_answers:
        raise ValueError('Нужны непустые списки одинаковой длины')
    return sum(abs(t-p) for t,p in zip(true_answers, predictions))/len(true_answers)

